@Override // com.macrovideo.v380.fragments.BaseFragment, com.macrovideo.v380.interfaces.HandleBackInterface
public boolean onBackPressed() {
    if (this.mActivity != null) {
        if (isChangeData()) {
            if (this.action == 1) {
                if (this.startTime.equals(this.defaultTime)) {
                    LogUtil.e(TAG, "<literal omitted>");
                    this.mActivity.showToast(R.string.select_start_time, new int[0]);
                    LogUtil.i(TAG, "<literal omitted>");
                    return false;
                }
                if (this.endTime.equals(this.defaultTime)) {
                    LogUtil.e(TAG, "<literal omitted>");
                    this.mActivity.showToast(R.string.select_end_time, new int[0]);
                    LogUtil.i(TAG, "<literal omitted>");
                    return false;
                }
            }
            WhiteLightConfigInfo whiteLightConfigInfo = new WhiteLightConfigInfo();
            whiteLightConfigInfo.setDefaultAction(this.defaultAction);
            whiteLightConfigInfo.setCapability(this.capability);
            try {
                WhiteLightConfigInfo.ActionData actionData = new WhiteLightConfigInfo.ActionData();
                actionData.setAction(this.action);
                String str = "<literal omitted>";
                actionData.setStartTime(this.defaultTime.equals(this.startTime) ? "<literal omitted>" : this.startTime);
                if (!this.defaultTime.equals(this.endTime)) {
                    str = this.endTime;
                }
                actionData.setEndTime(str);
                whiteLightConfigInfo.getActionData().add(actionData);
            } catch (Exception e) {
                e.printStackTrace();
            }
            whiteLightConfigInfo.setTotal(whiteLightConfigInfo.getActionData().size());
            whiteLightConfigInfo.setMainSwitch(this.mainSwitch);
            whiteLightConfigInfo.setMotionDetectionSwitch(this.motionDetectionSwitch);
            whiteLightConfigInfo.setHumanDetectionSwitch(this.humanDetectionSwitch);
            whiteLightConfigInfo.setCarDetectionSwitch(this.carDetectionSwitch);
            whiteLightConfigInfo.setPetDetectionSwitch(this.petDetectionSwitch);
            whiteLightConfigInfo.setAlarmWarnSwitch(this.alarmWarnSwitch);
            LogUtil.e(TAG, "<literal omitted>" + whiteLightConfigInfo.toString());
            setWhiteLightConfigInfo(this.version, this.mActivity.mDeviceInfo, whiteLightConfigInfo);
            LogUtil.i(TAG, "<literal omitted>");
            return true;
        }
        if (this.isReturn) {
            this.isReturn = false;
            LogUtil.e(TAG, "<literal omitted>");
            this.mActivity.showToast(R.string.str_setting_success, new int[0]);
            this.mActivity.finish();
        } else {
            this.mActivity.getSupportFragmentManager().popBackStack();
        }
        return false;
    }
    LogUtil.i(TAG, "<literal omitted>");
    return false;
}
